    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    long long ans = LLONG_MAX;

    // 枚举最终相同的数字 d
    for (int d = 0; d <= 9; d++) {
        long long cost = 0;
        // 计算第一个窗口的代价
        for (int i = 0; i < k; i++) {
            cost += abs(a[i] - d);
        }
        ans = min(ans, cost);

        // 滑动窗口
        for (int i = k; i < n; i++) {
            cost += abs(a[i] - d) - abs(a[i - k] - d);
            if (cost < ans) {
                ans = cost;
            }
        }
    }

    cout << ans << "\n";
    return 0;
}
